INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES 
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "Qual a principal limitação do Escore GRACE em comparação ao Escore TIMI na estratificação de risco da SCA sem supra de ST?", "options": {"a": "O GRACE é mais simples e rápido de calcular.", "b": "O GRACE exige o cálculo de variáveis mais complexas (FC, PA, creatinina, Killip) e geralmente requer o uso de softwares/aplicativos, enquanto o TIMI é uma soma simples de pontos.", "c": "O GRACE não avalia mortalidade.", "d": "O TIMI é mais preciso para predizer morte em 6 meses.", "e": "Nenhuma, ambos são iguais."}, "answer": "b", "rationale": "Embora o GRACE seja estatisticamente superior na predição de eventos, sua complexidade algorítmica é uma barreira na beira do leito sem ferramentas digitais.", "option_rationales": {"a": "Incorreta. TIMI é mais simples.", "b": "Correta. Diferença pragmática de aplicação.", "c": "Incorreta. GRACE avalia mortalidade hospitalar e em 6 meses.", "d": "Incorreta. GRACE é superior.", "e": "Incorreta."}, "difficulty": "media", "tags": ["Cardiologia", "Escores", "GRACE", "TIMI"]}', 116, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "Paciente masculino, 62 anos, com dor torácica típica a 4 horas. O ECG mostra supra de ST em parede lateral (DI, aVL, V5, V6). Após a realização de ICP primária bem-sucedida, o paciente mantém dor torácica e o supra de ST não reduz nem 50% após 90 minutos do procedimento. Esse fenômeno é indicativo de:", "options": {"a": "Sucesso absoluto.", "b": "Falha na reperfusão tecidual (microvascular), apesar da patência macrovascular da artéria epicárdica.", "c": "Efeito colateral do stent.", "d": "Normalidade.", "e": "Presença de marcapasso."}, "answer": "b", "rationale": "A não resolução do supra de ST é um marcador prognóstico ruim, sugerindo que o músculo não está sendo perfundido adequadamente ao nível capilar (no-reflow ou lesão de reperfusão).", "option_rationales": {"a": "Incorreta.", "b": "Correta. Falha de reperfusão microvascular.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "media", "tags": ["Cardiologia", "SCA", "Reperfusão", "ECG"]}', 117, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "A principal causa de morte hospitalar em pacientes que sobrevivem à fase arritmogênica inicial do infarto é:", "options": {"a": "Choque cardiogênico devido à perda de grande massa miocárdica (> 40% do VE).", "b": "Pneumonia aspirativa.", "c": "Infecção urinária.", "d": "Fratura de fêmur.", "e": "Cefaleia."}, "answer": "a", "rationale": "O choque cardiogênico por falência de bomba é a causa número 1 de óbito intra-hospitalar no IAM.", "option_rationales": {"a": "Correta. Principal causa de óbito hospitalar.", "b": "Incorreta.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Cardiologia", "Choque", "IAM", "Vascular"]}', 118, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "Sobre o uso de Heparina Não Fracionada (HNF) vs Heparina de Baixo Peso Molecular (HBPM - Enoxaparina) na SCA, qual a principal recomendação ao se optar pela HNF?", "options": {"a": "Não precisa monitorar.", "b": "É necessário monitorar o tempo de Tromboplastina Parcial Ativada (TTPa) a cada 6 horas para manter o nível terapêutico (1,5 a 2,5x o controle).", "c": "Pode ser dada apenas uma vez ao dia.", "d": "É proibida em idosos.", "e": "Causa mais sangramento que a enoxaparina universalmente."}, "answer": "b", "rationale": "A HNF tem farmacocinética errática, exigindo controle laboratorial rigoroso, ao contrário da HBPM que tem dose fixa por peso.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Manejo laboratorial da HNF.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Cardiologia", "Farmacologia", "Heparina", "SCA"]}', 119, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "Qual o achado ecocardiográfico que define a DISFUNÇÃO VENTRICULAR grave pós-infarto, sendo critério para início precoce de Espironolactona (estudo EPHESUS)?", "options": {"a": "Fração de Ejeção do Ventrículo Esquerdo (FEVE) <= 40% associada a sinais de IC ou Diabetes.", "b": "Presença de refluxo valvar leve.", "c": "Ventrículo Direito dilatado.", "d": "Átrio Esquerdo normal.", "e": "Espessamento do pericárdio."}, "answer": "a", "rationale": "O estudo EPHESUS demonstrou benefício da Eplerenona (e por extrapolação, Espironolactona) em pacientes pós-infarto com disfunção de VE significante.", "option_rationales": {"a": "Correta. Indicação baseada em grande estudo clínico.", "b": "Incorreta.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "moderada", "tags": ["Cardiologia", "IC", "SCA", "Farmacologia"]}', 120, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "A cineangiocoronariografia de um paciente mostra uma lesão de 90% em tronco de coronária esquerda. O paciente tem estenose aórtica grave associada. Qual a melhor conduta?", "options": {"a": "Apenas ICP com stent.", "b": "Cirurgia combinada: Revascularização do Miocárdio (CRVM) + Troca Valvar Aórtica.", "c": "Apenas tratamento clínico para ambas.", "d": "TAVI seguida de ICP.", "e": "Aguardar 1 ano para operar."}, "answer": "b", "rationale": "Quando há indicação cirúrgica para coronárias (tronco) e para válvula (estenose grave), o procedimento deve ser combinado para aproveitar o tempo de CEC e reduzir riscos futuros.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Conduta cirúrgica padrão.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "media", "tags": ["Cardiologia", "Cirurgia", "Válvulas", "Tronco"]}', 121, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "A principal vantagem da via de acesso RADIAL sobre a FEMORAL na cineangiocoronariografia, segundo o estudo MATRIX, é:", "options": {"a": "É mais fácil de aprender.", "b": "Redução significativa de complicações hemorrágicas no sítio de punção e mortalidade global em centros experientes.", "c": "O exame é mais rápido.", "d": "Usa-se menos contraste.", "e": "Não há risco de AVC."}, "answer": "b", "rationale": "O acesso radial reduz sangramentos maiores e complicações vasculares locais, o que impacta positivamente na mortalidade.", "option_rationales": {"a": "Incorreta. Radial é tecnicamente mais difícil.", "b": "Correta. Evidência robusta atual.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "media", "tags": ["Cardiologia", "Hemodinâmica", "Radial", "Segurança"]}', 122, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "Qual a medicação utilizada no teste farmacológico de estresse para cintilografia miocárdica (MIBI) que age como um potente VASODILATADOR das coronárias normais, revelando a reserva de fluxo reduzida nas coronárias estenosadas (fenômeno do roubo de fluxo)?", "options": {"a": "Dobutamina.", "b": "Dipiridamol ou Adenosina.", "c": "Atropina.", "d": "Propranolol.", "e": "Heparina."}, "answer": "b", "rationale": "Dipiridamol e Adenosina causam hiperemia máxima. Vasos com estenose já estão dilatados ao máximo compensatoriamente e não dilatam mais, enquanto os normais dilatam, gerando a diferença de captação do radiotraçador.", "option_rationales": {"a": "Incorreta. Dobutamina aumenta o consumo (estresse inotrópico).", "b": "Correta. Farmacologia do estresse cintilográfico.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Cardiologia", "Cintilografia", "Farmacologia", "Isquemia"]}', 123, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "Um paciente tabagista crônico, com dor torácica que surge SEMPRE no mesmo horário da madrugada, em repouso. O ECG durante a dor mostra supra de ST que desaparece completamente após o uso de nitrato sublingual e fim da dor. Qual o diagnóstico?", "options": {"a": "Angina Estável.", "b": "Angina de Prinzmetal (Vasoespástica).", "c": "IAM anterior extenso.", "d": "Dissecção de Aorta.", "e": "Pneumonitite."}, "answer": "b", "rationale": "A angina de Prinzmetal ocorre por espasmo coronariano focal, mimetizando eletrocardiograficamente um IAM com supra, mas com reversão rápida.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Quadro clínico clássico de vasoespasmo.", "c": "Incorreta. IAM não reverte o supra em minutos com nitrato.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Cardiologia", "Prinzmetal", "Vasoespasmo", "SCA"]}', 124, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "O uso de Inibidores da ECA (ex: Enalapril) no pós-infarto imediato é recomendado principalmente nas primeiras 24 horas para evitar:", "options": {"a": "Aumento do açúcar.", "b": "Remodelamento ventricular adverso (dilatação e perda de forma do coração).", "c": "Infecção pulmonar.", "d": "Ganho de peso.", "e": "Cefaleia."}, "answer": "b", "rationale": "O iECA bloqueia a angiotensina II, que é um potente mediador de fibrose e crescimento celular patológico no miocárdio infartado.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Papel do iECA na preservação da função ventricular.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Cardiologia", "Farmacologia", "iECA", "Remodelamento"]}', 125, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "A principal contraindicação para a realização de um teste ergométrico em um paciente com dor torácica é:", "options": {"a": "Angina instável em repouso nas últimas 48 horas ou infarto agudo em evolução.", "b": "Idade acima de 60 anos.", "c": "Obesidade leve.", "d": "História de asma.", "e": "Uso de aspirina."}, "answer": "a", "rationale": "É perigoso estressar o coração durante uma fase de instabilidade de placa ou necrose aguda.", "option_rationales": {"a": "Correta. Contraindicação absoluta de segurança.", "b": "Incorreta.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Cardiologia", "Ergometria", "Contraindicação", "SCA"]}', 126, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "Qual o principal mecanismo de ação dos Fibrinolíticos (ex: Alteplase, Tenecteplase) na SCA com supra de ST?", "options": {"a": "Impedir a agregação das plaquetas.", "b": "Ativar a conversão do plasminogênio em plasmina, que cliva as redes de fibrina do trombo.", "c": "Dilatar as coronárias.", "d": "Abaixar a pressão arterial.", "e": "Diminuir o oxigênio."}, "answer": "b", "rationale": "Fibrinolíticos ''dissolvem'' o coágulo de fibrina já formado.", "option_rationales": {"a": "Incorreta. Isso é papel dos antiagregantes.", "b": "Correta. Mecanismo bioquímico da fibrinólise.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Cardiologia", "Farmacologia", "Fibrinólise", "SCA"]}', 127, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "Um paciente pós-infarto anterior extenso apresenta febre persistente, dor torácica pleurítica e derrame pericárdico 4 semanas após o evento inicial. Qual o diagnóstico e o tratamento de escolha?", "options": {"a": "Reinfarto; cateterismo.", "b": "Síndrome de Dressler; AAS em altas doses e/ou Colchicina.", "c": "Insuciência Renal; Diálise.", "d": "Tuberculose; Rifampicina.", "e": "Pulsão de marcapasso."}, "answer": "b", "rationale": "Dressler é uma pericardite autoimune tardia pós-infarto.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Reconhecimento de complicação imunológica.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "media", "tags": ["Cardiologia", "Dressler", "Pericardite", "Pós-Infarto"]}', 128, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "Sobre o manejo da SCA em hospitais sem hemodinâmica, se a transferência para ICP primária não for possível em tempo hábil, o fibrinolítico é realizado. Qual o principal sinal de SUCESSO da fibrinólise (reperfusão)?", "options": {"a": "Aumento da dor.", "b": "Redução superior a 50% do supra de ST na derivação de maior supra em até 90 minutos após o início.", "c": "Aparecimento de onda P.", "d": "Aumento da frequência cardíaca.", "e": "Vômitos intensos."}, "answer": "b", "rationale": "A queda do ST associada ao alívio da dor e ao aparecimento de arritmias de reperfusão (como RIVA) indicam sucesso.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Critério elétrico de reperfusão.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "media", "tags": ["Cardiologia", "Fibrinólise", "Reperfusão", "SCA"]}', 129, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "A principal indicação para o uso de balão de contrapulsação intra-aórtico (BIA) no infarto agudo é:", "options": {"a": "Aliviar a dor leve.", "b": "Choque cardiogênico refratário ou complicações mecânicas (CIV, Insuficiência Mitral aguda) como ponte para cirurgia.", "c": "Tratar a hipertensão.", "d": "Drenar derrame pericárdico.", "e": "Aumentar a diurese."}, "answer": "b", "rationale": "O BIA reduz a pós-carga do VE e aumenta a perfusão coronariana diastólica, oferecendo suporte hemodinâmico temporário.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Uso clássico de suporte circulatório mecânico.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "media", "tags": ["Cardiologia", "BIA", "Choque", "Suporte"]}', 130, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "A cineangiocoronariografia de um paciente mostra uma ponte de safena antiga ocluída. O paciente tem angina refratária. Qual o risco do tratamento percutâneo (ICP) de pontes de safena degeneradas em comparação com artérias nativas?", "options": {"a": "Nenhum risco extra.", "b": "Alto risco de ''no-reflow'' por embolização distal de detritos friáveis da ponte.", "c": "Risco de pneumonia.", "d": "Risco de surdez.", "e": "Risco de alergia ao látex."}, "answer": "b", "rationale": "Pontes de safena velhas contêm material friável que se desprende durante a angioplastia. Dispositivos de proteção distal (filtros) são frequentemente usados para mitigar esse risco.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Desafio técnico da intervenção em enxertos venosos.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "moderada", "tags": ["Cardiologia", "Intervenção", "Safena", "Hemodinâmica"]}', 131, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "Qual dos seguintes bloqueadores dos canais de cálcio é preferencial no tratamento da Angina de Prinzmetal por seu potente efeito vasodilatador coronariano?", "options": {"a": "Verapamil ou Diltiazem.", "b": "Nifedipina de curta duração.", "c": "Atenolol.", "d": "Carvedilol.", "e": "Metoprolol."}, "answer": "a", "rationale": "Os bloqueadores não-di-hidropiridínicos (verapamil/diltiazem) são excelentes para prevenir o vasoespasmo. Di-hidropiridínicos de longa ação (Anlodipino) também podem ser usados.", "option_rationales": {"a": "Correta. Tratamento de escolha para vasoespasmo.", "b": "Incorreta. Pode causar taquicardia reflexa deletéria.", "c": "Incorreta. Betabloqueador.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "media", "tags": ["Cardiologia", "Prinzmetal", "Farmacologia", "SCA"]}', 132, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "A principal limitação da cintilografia miocárdica em pacientes com bloqueio de ramo esquerdo (BRE) é:", "options": {"a": "O paciente não pode entrar na máquina.", "b": "Falsos positivos na parede septal (artefatos de movimento septal anômalo induzidos pelo BRE).", "c": "O contraste é tóxico para os rins.", "d": "Não avalia isquemia lateral.", "e": "Aumenta o risco de asma."}, "answer": "b", "rationale": "O BRE altera a cinética do septo interventricular, o que pode mimetizar uma hipocaptação septal na cintilografia. Nesses casos, prefere-se o estresse farmacológico com adenosina/dipiridamol em vez do esforço físico.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Artefato clássico de imagem em medicina nuclear.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "moderada", "tags": ["Cardiologia", "Cintilografia", "BRE", "Diagnóstico"]}', 133, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "O ''Escore SYNTAX'' é uma ferramenta utilizada principalmente para ajudar na decisão entre:", "options": {"a": "Aspirina vs Clopidogrel.", "b": "Cirurgia de Revascularização (CRVM) vs Intervenção Percutânea (ICP) em pacientes com doença multiarterial ou de tronco de esquerda.", "c": "Dieta vs Exercício.", "d": "Nitrato vs Morfina.", "e": "Alta hospitalar vs Internação na UTI."}, "answer": "b", "rationale": "O SYNTAX pontua a complexidade anatômica das lesões. Escore baixo favorece ICP; escore alto favorece CRVM.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Uso do Heart Team no processo de decisão.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "media", "tags": ["Cardiologia", "SYNTAX", "Conduta", "Vascular"]}', 134, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "Qual a principal função da Colchicina no tratamento pós-infarto agudo do miocárdio, conforme sugerido pelo estudo COLCOT?", "options": {"a": "Abaixar o colesterol.", "b": "Reduzir a inflamação sistêmica e eventos cardiovasculares recorrentes (morte súbita, AVC, revascularização de urgência).", "c": "Tratar a gota.", "d": "Impedir o sangramento digestivo.", "e": "Aumentar a força do coração."}, "answer": "b", "rationale": "A teoria inflamatória da aterosclerose ganha força com estudos como COLCOT e CANTOS (canakinumabe), mostrando que reduzir a inflamação protege o paciente.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Uso moderno de droga antiga na cardiologia.", "c": "Incorreta. Uso original, mas não o alvo neste contexto.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "media", "tags": ["Cardiologia", "Inflamação", "Colchicina", "Pós-Infarto"]}', 135, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "A principal indicação para o uso de Nitrato de Isossorbida (oral) em um paciente com coronariopatia crônica é:", "options": {"a": "Reduzir a frequência cardíaca.", "b": "Profilaxia de angina aos esforços (aumentar a tolerância ao exercício).", "c": "Tratar fibrilação atrial.", "d": "Aumentar a glicose.", "e": "Diminuir o ácido úrico."}, "answer": "b", "rationale": "Nitratos de longa ação ajudam a prevenir episódios de angina ao longo do dia.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Papel na angina estável crônica.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Cardiologia", "Farmacologia", "Nitratos", "Estável"]}', 136, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "Qual a complicação mais temida do uso de Inibidores da Fosfodiesterase V (Sildenafila) em pacientes que JÁ fazem uso de nitratos?", "options": {"a": "Cegueira.", "b": "Hipotensão severa e persistente que pode evoluir para baixo débito e morte.", "c": "Surdez súbita.", "d": "Rash cutâneo.", "e": "Perda de apetite."}, "answer": "b", "rationale": "A interação causa vasodilatação sistêmica maciça.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Contraindicação absoluta vital.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Cardiologia", "Farmacologia", "Segurança", "Interação"]}', 137, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "A cineangiocoronariografia mostra uma lesão de 80% em ramo Diagonal. O paciente é assintomático. Qual a conduta?", "options": {"a": "Stent de urgência.", "b": "Tratamento clínico otimizado (ramos diagnonais pequenos e assintomáticos não exigem revascularização rotineira).", "c": "Fibrinólise.", "d": "Cirurgia de mamária.", "e": "Apenas AAS em dose alta."}, "answer": "b", "rationale": "Lesões em ramos pequenos sem isquemia demonstrada devem ser manejadas clinicamente.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Conservadorismo clínico baseado em evidência.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "media", "tags": ["Cardiologia", "Conduta", "Isquemia", "Invasivo"]}', 138, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "O estudo COMPASS demonstrou benefício cardiovascular ao utilizar qual estratégia antitrombótica em pacientes com doença arterial coronariana estável e/ou doença arterial periférica?", "options": {"a": "Aspirina + Clopidogrel.", "b": "Aspirina + Rivaroxabana (dose baixa - 2,5 mg 2x ao dia).", "c": "Apenas Rivaroxabana 20 mg/dia.", "d": "Varfarina + Heparina.", "e": "Aspirina + Varfarina."}, "answer": "b", "rationale": "A combinação de baixa dose de um NOAC com aspirina reduziu eventos isquêmicos e mortalidade, com aumento aceitável de sangramento não fatal.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Estratégia moderna de proteção dual (dual pathway inhibition).", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "moderada", "tags": ["Cardiologia", "COMPASS", "Antitrombóticos", "Vascular"]}', 139, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "Qual o achado ECG que sugere INFARTO DE ÁTRIO em associação com infarto ventricular?", "options": {"a": "Supra de ST.", "b": "Elevação ou depressão do segmento PR em relação à linha de base TP.", "c": "Onda P bimodal.", "d": "Ausência de onda P.", "e": "Aumento do intervalo QT."}, "answer": "b", "rationale": "O segmento PR representa a repolarização atrial e pode ser alterado no infarto atrial.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Sinal eletrocardiográfico específico mas raro.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "dificil", "tags": ["Cardiologia", "ECG", "Infarto Atrial", "SCA"]}', 140, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "A principal limitação da Ressonância Magnética Cardíaca com estresse por adenosina em pacientes claustrofóbicos é:", "options": {"a": "Apenas o medo do paciente.", "b": "Inviabilidade técnica de captar imagens de qualidade se o paciente não colaborar ou se mexer durante as sequências de longa duração.", "c": "Radiação excessiva.", "d": "O contraste gadolínio causa sempre anafilaxia.", "e": "Não vê o septo."}, "answer": "b", "rationale": "A RM cardíaca exige que o paciente fique imóvel e realize comandos de apneia.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Aspecto prático do exame.", "c": "Incorreta. RM não usa radiação ionizante.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Cardiologia", "Ressonância", "Segurança", "Diagnóstico"]}', 141, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "Qual a dose de carga da Aspirina recomendada na fase aguda de uma SCA (IAM)?", "options": {"a": "100 mg via oral.", "b": "162 a 325 mg (preferencialmente mastigada para absorção mais rápida).", "c": "500 mg endovenoso.", "d": "1000 mg via retal.", "e": "Aspirina não é mais usada."}, "answer": "b", "rationale": "A dose de ataque de aspirina é fundamental para inibir a tromboxano A2 precocemente.", "option_rationales": {"a": "Incorreta. Abaixo do recomendado para ataque.", "b": "Correta. Recomendação universal das diretrizes.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Cardiologia", "Farmacologia", "Aspirina", "SCA"]}', 142, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "Sobre o manejo da dor torácica na Sala de Emergência, qual medicação deve ser PRIORIZADA em pacientes com quadro isquêmico e insuficiência cardíaca associada (edema pulmonar)?", "options": {"a": "Nitrato (vasodilatador).", "b": "Dobutamina.", "c": "Aspirina.", "d": "Soro fisiológico 2 litros.", "e": "Betabloqueador endovenoso."}, "answer": "a", "rationale": "Nitratos reduzem a pré e pós-carga, aliviando a congestão pulmonar.", "option_rationales": {"a": "Correta. Benefício hemodinâmico e anti-isquêmico duplo.", "b": "Incorreta. Pode aumentar o consumo de O2 e piorar a isquemia.", "c": "Incorreta. Importante, mas não resolve a congestão aguda.", "d": "Incorreta. Piora o edema agudo.", "e": "Incorreta. Contraindicado na fase aguda descompensada da IC."}, "difficulty": "media", "tags": ["Cardiologia", "Emergência", "Nitrato", "IC"]}', 143, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "O termo ''angina instável'' é definido por dor torácica isquêmica que apresenta qual das seguintes características?", "options": {"a": "Ocorre apenas após exercício pesado.", "b": "Ocorre em repouso (geralmente > 20 min), é de início recente (de novo) ou apresenta padrão em crescendo (mais frequente, longa ou intensa do que antes).", "c": "Melhora sempre com repouso em 1 minuto.", "d": "Não tem relação com as coronárias.", "e": "Cura-se com antibiótico."}, "answer": "b", "rationale": "A instabilidade sugere um processo de placa ativa sem necrose transmural (troponina pode ser negativa ou levemente elevada).", "option_rationales": {"a": "Incorreta.", "b": "Correta. Definição clínica de instabilidade.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Cardiologia", "Angina Instável", "Definição", "SCA"]}', 144, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "Em pacientes idosos com IAMssST, a principal preocupação no uso de antiagregantes plaquetários duplos potentes (ex: Prasugrel) é:", "options": {"a": "Eficácia reduzida.", "b": "Alto risco de sangramento intracraniano e gastrointestinal (contraindicado prasugrel se história de AVC/AIT prévio ou idade > 75 anos em alguns protocolos).", "c": "Gosto ruim da medicação.", "d": "Aumento do colesterol.", "e": "Piora da audição."}, "answer": "b", "rationale": "O prasugrel é muito potente e seu uso deve ser criterioso em idosos e pacientes de baixo peso pelo risco hemorrágico.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Limitação de segurança baseada no estudo TRITON-TIMI 38.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "moderada", "tags": ["Cardiologia", "Farmacologia", "Prasugrel", "Segurança"]}', 145, 'draft');
